28	func TestTerminalBackgroundByProfile(t *testing.T) {
29		bg := lipgloss.Color("#1e1e2e")
30	
31		t.Run("TrueColor keeps the exact colour", func(t *testing.T) {
32			got := terminalBackground(colorprofile.TrueColor, bg)
33			if got == nil || theme.Hex(got) != "#1e1e2e" {
34				t.Fatalf("got %v, want #1e1e2e", got)
35			}
36		})
37	
38		t.Run("ANSI256 converts to the colour the painted cells get", func(t *testing.T) {
39			got := terminalBackground(colorprofile.ANSI256, bg)
40			want := colorprofile.ANSI256.Convert(bg)
41			if got != want {
42				t.Fatalf("got %#v, want %#v", got, want)
43			}
44			if _, ok := got.(ansi.IndexedColor); !ok {
45				t.Fatalf("got %T, want ansi.IndexedColor", got)
46			}
47			if got == color.Color(bg) {
48				t.Fatal("ANSI256 result equals the exact colour: a seam would show against painted cells")
49			}
50		})
51	
52		for _, tc := range []struct {
53			name    string
54			profile colorprofile.Profile
55			bg      color.Color
56		}{
57			{"ANSI (16 colours)", colorprofile.ANSI, bg},
58			{"ASCII (NO_COLOR)", colorprofile.ASCII, bg},
59			{"NoTTY", colorprofile.NoTTY, bg},
60			{"Unknown (zero value)", colorprofile.Unknown, bg},
61			{"nil colour", colorprofile.TrueColor, nil},
62			{"NoColor", colorprofile.TrueColor, lipgloss.NoColor{}},
63			{"nil colour, ANSI256", colorprofile.ANSI256, nil},
64		} {
65			t.Run("nil for "+tc.name, func(t *testing.T) {
66				if got := terminalBackground(tc.profile, tc.bg); got != nil {
67					t.Fatalf("got %#v, want nil", got)
68				}
69			})
70		}
71	}
