73	// TestTerminalBackgroundIsComparableOnEveryShippedTheme: the renderer compares
74	// View.BackgroundColor with !=, so a non-comparable dynamic type would panic.
75	func TestTerminalBackgroundIsComparableOnEveryShippedTheme(t *testing.T) {
76		files, err := filepath.Glob("../../themes/*.json")
77		if err != nil {
78			t.Fatal(err)
79		}
80		if len(files) == 0 {
81			t.Fatal("no theme found under themes/*.json")
82		}
83		themes := map[string]*theme.Theme{"default": theme.DefaultTheme()}
84		for _, f := range files {
85			data, err := os.ReadFile(f)
86			if err != nil {
87				t.Fatal(err)
88			}
89			var th theme.Theme
90			if err := json.Unmarshal(data, &th); err != nil {
91				t.Fatalf("%s: %v", f, err)
92			}
93			themes[strings.TrimSuffix(filepath.Base(f), ".json")] = &th
94		}
95		if want := len(files) + 1; len(themes) != want {
96			t.Fatalf("got %d themes, want %d (default + %d files)", len(themes), want, len(files))
97		}
98		t.Cleanup(func() { theme.ApplyTheme(theme.DefaultTheme()) })
99	
100		for name, th := range themes {
101			for _, p := range []colorprofile.Profile{colorprofile.TrueColor, colorprofile.ANSI256} {
102				t.Run(name+"/"+p.String(), func(t *testing.T) {
103					theme.ApplyTheme(theme.DefaultTheme())
104					theme.ApplyTheme(th)
105					got := terminalBackground(p, theme.ColorBackground)
106					if got == nil {
107						t.Fatal("got nil, want a colour")
108					}
109					if !reflect.TypeOf(got).Comparable() {
110						t.Fatalf("%T is not comparable", got)
111					}
112					_ = got == terminalBackground(p, theme.ColorBackground) // would panic if not comparable
113				})
114			}
115		}
116	}
