298	// writeTheme writes a valid theme named name under the isolated HOME's theme
299	// directory, with the given background.
300	func writeTheme(t *testing.T, name, background string) {
301		t.Helper()
302		dir, err := theme.ThemeDir()
303		if err != nil {
304			t.Fatal(err)
305		}
306		if err := os.MkdirAll(dir, 0o755); err != nil {
307			t.Fatal(err)
308		}
309		th := theme.DefaultTheme()
310		th.Name = name
311		th.ColorBackground = background
312		data, err := json.Marshal(th)
313		if err != nil {
314			t.Fatal(err)
315		}
316		if err := os.WriteFile(filepath.Join(dir, name+".json"), data, 0o644); err != nil {
317			t.Fatal(err)
318		}
319	}
