329	func saveTheme(a *App, name string) {
330		cfg := testConfig()
331		cfg.App.Theme = name
332		a.Update(configuration.ConfigSavedMsg{Config: cfg, ThemeChanged: true})
333	}
334	
335	func resetThemeAfter(t *testing.T) {
336		t.Helper()
337		t.Cleanup(func() {
338			theme.ApplyTheme(theme.DefaultTheme())
339			theme.CurrentThemeName = "default"
340		})
341		theme.ApplyTheme(theme.DefaultTheme())
342		theme.CurrentThemeName = "default"
343	}
344	
345	// DEVDESK-209 step 3: the terminal background follows the theme.
346	func TestTheTerminalBackgroundFollowsTheTheme(t *testing.T) {
347		a := router(t, &fakeView{body: "hello"}) // isolates HOME
348		resetThemeAfter(t)
349		writeTheme(t, "light", "#ffffff")
350		sendProfile(t, a, colorprofile.TrueColor)
351		if got := bgHex(a); got != "#1e1e2e" {
352			t.Fatalf("default theme: got %s, want #1e1e2e", got)
353		}
354	
355		saveTheme(a, "light")
356		if got := bgHex(a); got != "#ffffff" {
357			t.Errorf("after switching to the light theme: got %s, want #ffffff", got)
358		}
359	
360		saveTheme(a, "default")
361		if got := bgHex(a); got != "#1e1e2e" {
362			t.Errorf("after switching back to the default theme: got %s, want #1e1e2e", got)
363		}
364	}
365	
366	func TestARefusedThemeKeepsThePreviousTerminalBackground(t *testing.T) {
367		a := router(t, &fakeView{body: "hello"})
368		resetThemeAfter(t)
369		writeTheme(t, "light", "#ffffff")
370		writeTheme(t, "broken", "#ggg")
371		sendProfile(t, a, colorprofile.TrueColor)
372	
373		saveTheme(a, "broken")
374		if got := bgHex(a); got != "#1e1e2e" {
375			t.Errorf("refused theme from default: got %s, want #1e1e2e kept", got)
376		}
377	
378		saveTheme(a, "light")
379		saveTheme(a, "broken")
380		if got := bgHex(a); got != "#ffffff" {
381			t.Errorf("refused theme from light: got %s, want #ffffff kept", got)
382		}
383	}
384	
385	func TestAThemeSwitchOnANonTrueColorProfile(t *testing.T) {
386		a := router(t, &fakeView{body: "hello"})
387		resetThemeAfter(t)
388		writeTheme(t, "light", "#ffffff")
389	
390		sendProfile(t, a, colorprofile.ASCII)
391		saveTheme(a, "light")
392		if got := bgHex(a); got != "<nil>" {
393			t.Errorf("ASCII: got %s, want nil", got)
394		}
395	
396		sendProfile(t, a, colorprofile.ANSI256)
397		// theme.Hex does not read an indexed colour, so compare real RGBA values.
398		got := a.View().BackgroundColor
399		if got == nil {
400			t.Fatal("ANSI256 after the switch: background is nil")
401		}
402		wr, wg, wb, wa := colorprofile.ANSI256.Convert(theme.ColorBackground).RGBA()
403		gr, gg, gb, ga := got.RGBA()
404		if gr != wr || gg != wg || gb != wb || ga != wa {
405			t.Errorf("ANSI256 after the switch: got %v %v %v %v, want %v %v %v %v", gr, gg, gb, ga, wr, wg, wb, wa)
406		}
407	}
408	
409	func themeSaved(cfg *config.Config) tea.Msg {
410		return configuration.ConfigSavedMsg{Config: cfg, ThemeChanged: true}
411	}
