51	// waitOut polls until cond(out) holds, or fails after a guard timeout.
52	func waitOut(t *testing.T, out *lockedBuffer, what string, cond func(string) bool) {
53		t.Helper()
54		deadline := time.Now().Add(5 * time.Second)
55		for !cond(out.String()) {
56			if time.Now().After(deadline) {
57				t.Errorf("timed out waiting for %s; output so far: %q", what, out.String())
58				return
59			}
60			time.Sleep(5 * time.Millisecond)
61		}
62	}
