64	// runRouter runs a around a real program writing to a buffer, after the first
65	// frame ("hello") script runs; the program is given profile. It fails the test
66	// when the program outlives a guard timeout.
67	func runRouter(t *testing.T, a *App, profile colorprofile.Profile, script func(p *tea.Program, out *lockedBuffer)) (string, error) {
68		t.Helper()
69		out := &lockedBuffer{}
70		p := tea.NewProgram(a, tea.WithInput(nil), tea.WithOutput(out),
71			tea.WithWindowSize(100, 30), tea.WithoutSignalHandler(), tea.WithColorProfile(profile))
72		go func() {
73			waitOut(t, out, "the first frame", func(s string) bool { return strings.Contains(s, "hello") })
74			if profile != colorprofile.Ascii {
75				// The first SET may land after the first frame; an exit sent
76				// before it would race with the write of the SET.
77				waitOut(t, out, "the first background SET", func(s string) bool { return strings.Contains(s, bgSet) })
78			}
79			script(p, out)
80		}()
81		type result struct{ err error }
82		done := make(chan result, 1)
83		go func() { _, err := p.Run(); done <- result{err} }()
84		select {
85		case r := <-done:
86			return out.String(), r.err
87		case <-time.After(10 * time.Second):
88			p.Kill()
89			t.Fatal("the program did not exit")
90			return "", nil
91		}
92	}
