232	// TestOnlyTheRouterSetsTheTerminalBackground: the terminal's background is
233	// terminal state, so like AltScreen only the router (internal/app/view.go)
234	// sets it. Any other assignment or composite-literal field named
235	// BackgroundColor in non-test code is reported with file:line.
236	func TestOnlyTheRouterSetsTheTerminalBackground(t *testing.T) {
237		const owner = "internal/app/view.go"
238		root := filepath.Join("..", "..")
239		fset := token.NewFileSet()
240		var offences []string
241		ownerSets := false
242	
243		err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
244			if err != nil {
245				return err
246			}
247			rel, _ := filepath.Rel(root, path)
248			rel = filepath.ToSlash(rel)
249			if d.IsDir() {
250				switch d.Name() {
251				case ".git", ".worktrees", "vendor", "node_modules":
252					return filepath.SkipDir
253				}
254				return nil
255			}
256			if !strings.HasSuffix(rel, ".go") || strings.HasSuffix(rel, "_test.go") {
257				return nil
258			}
259			f, err := parser.ParseFile(fset, path, nil, 0)
260			if err != nil {
261				return err
262			}
263			report := func(pos token.Pos) {
264				if rel == owner {
265					ownerSets = true
266					return
267				}
268				offences = append(offences, fset.Position(pos).String())
269			}
270			ast.Inspect(f, func(n ast.Node) bool {
271				switch x := n.(type) {
272				case *ast.AssignStmt:
273					for _, lhs := range x.Lhs {
274						if sel, ok := lhs.(*ast.SelectorExpr); ok && sel.Sel.Name == "BackgroundColor" {
275							report(sel.Pos())
276						}
277					}
278				case *ast.KeyValueExpr:
279					if id, ok := x.Key.(*ast.Ident); ok && id.Name == "BackgroundColor" {
280						report(id.Pos())
281					}
282				}
283				return true
284			})
285			return nil
286		})
287		if err != nil {
288			t.Fatal(err)
289		}
290		for _, o := range offences {
291			t.Errorf("%s sets BackgroundColor; only %s may (the router owns terminal state)", o, owner)
292		}
293		if !ownerSets {
294			t.Errorf("%s never assigns BackgroundColor: the guard would pass vacuously", owner)
295		}
296	}
