20	// DEVDESK-209 step 4: the terminal background is set and restored by Bubble
21	// Tea, proven on the bytes a real tea.Program writes (no TTY). These pin the
22	// framework's contract: a version bump that breaks it fails here.
23	//
24	// A panic test makes Bubble Tea print the stack trace to stderr; that is
25	// accepted noise.
26	
27	const (
28		bgReset = "\x1b]111\x07"
29		bgSet   = "\x1b]11;"
30	)
31	
32	var bgSeqRe = regexp.MustCompile("\x1b\\](111|11;[^\x07\x1b]*)(\x07|\x1b\\\\)")
33	
34	// bgSequences returns the ordered "set background" (OSC 11) and "reset
35	// background" (OSC 111) sequences found in out. Both are searched as whole
36	// sequences because they share the ESC ] 11 prefix.
37	func bgSequences(out string) []string {
38		var seqs []string
39		for _, m := range bgSeqRe.FindAllStringSubmatch(out, -1) {
40			if m[1] == "111" {
41				seqs = append(seqs, bgReset)
42			} else {
43				seqs = append(seqs, "\x1b]"+m[1]+"\x07")
44			}
45		}
46		return seqs
47	}
48	
49	func setOf(hex string) string { return bgSet + hex + "\x07" }
50	
51	// waitOut polls until cond(out) holds, or fails after a guard timeout.
52	func waitOut(t *testing.T, out *lockedBuffer, what string, cond func(string) bool) {
53		t.Helper()
54		deadline := time.Now().Add(5 * time.Second)
55		for !cond(out.String()) {
56			if time.Now().After(deadline) {
57				t.Errorf("timed out waiting for %s; output so far: %q", what, out.String())
58				return
59			}
60			time.Sleep(5 * time.Millisecond)
61		}
62	}
63	
64	// runRouter runs a around a real program writing to a buffer, after the first
65	// frame ("hello") script runs; the program is given profile. It fails the test
66	// when the program outlives a guard timeout.
67	func runRouter(t *testing.T, a *App, profile colorprofile.Profile, script func(p *tea.Program, out *lockedBuffer)) (string, error) {
68		t.Helper()
69		out := &lockedBuffer{}
70		p := tea.NewProgram(a, tea.WithInput(nil), tea.WithOutput(out),
71			tea.WithWindowSize(100, 30), tea.WithoutSignalHandler(), tea.WithColorProfile(profile))
72		go func() {
73			waitOut(t, out, "the first frame", func(s string) bool { return strings.Contains(s, "hello") })
74			if profile != colorprofile.Ascii {
75				// The first SET may land after the first frame; an exit sent
76				// before it would race with the write of the SET.
77				waitOut(t, out, "the first background SET", func(s string) bool { return strings.Contains(s, bgSet) })
78			}
79			script(p, out)
80		}()
81		type result struct{ err error }
82		done := make(chan result, 1)
83		go func() { _, err := p.Run(); done <- result{err} }()
84		select {
85		case r := <-done:
86			return out.String(), r.err
87		case <-time.After(10 * time.Second):
88			p.Kill()
89			t.Fatal("the program did not exit")
90			return "", nil
91		}
92	}
