94	func endsWithReset(t *testing.T, out string) {
95		t.Helper()
96		seqs := bgSequences(out)
97		if len(seqs) == 0 || seqs[len(seqs)-1] != bgReset {
98			t.Errorf("bgSequences = %q, want a last element %q", seqs, bgReset)
99		}
100	}
