227	// fakeExec stands in for the child of tea.Exec. During Run it snapshots what
228	// the program has written so far: the child must see the terminal's own
229	// background, so the last background sequence before Run is a reset.
230	type fakeExec struct {
231		out *lockedBuffer
232		err error
233	
234		mu       sync.Mutex
235		captured string
236	}
237	
238	func (f *fakeExec) Run() error {
239		f.mu.Lock()
240		f.captured = f.out.String()
241		f.mu.Unlock()
242		return f.err
243	}
244	func (f *fakeExec) SetStdin(io.Reader)  {}
245	func (f *fakeExec) SetStdout(io.Writer) {}
246	func (f *fakeExec) SetStderr(io.Writer) {}
247	
248	func (f *fakeExec) snapshot() string {
249		f.mu.Lock()
250		defer f.mu.Unlock()
251		return f.captured
252	}
253	
254	// execView runs fe through tea.Exec on a key and reports cb's error.
255	type execView struct {
256		fakeView
257		fe *fakeExec
258		cb chan error
259	}
260	
261	func (v *execView) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
262		if _, ok := msg.(tea.KeyPressMsg); ok {
263			return v, tea.Exec(v.fe, func(err error) tea.Msg { v.cb <- err; return nil })
264		}
265		return v, nil
266	}
267	
268	func testExec(t *testing.T, runErr error) {
269		t.Helper()
270		out := &lockedBuffer{}
271		_ = out
272		fe := &fakeExec{err: runErr}
273		v := &execView{fakeView: fakeView{body: "hello"}, fe: fe, cb: make(chan error, 1)}
274		a := programRouter(t, v)
275	
276		got, err := runRouter(t, a, colorprofile.TrueColor, func(p *tea.Program, out *lockedBuffer) {
277			fe.out = out
278			p.Send(testutil.Key("x"))
279			select {
280			case cbErr := <-v.cb:
281				if !errors.Is(cbErr, runErr) {
282					t.Errorf("exec callback got %v, want %v", cbErr, runErr)
283				}
284			case <-time.After(5 * time.Second):
285				t.Error("the exec callback never ran")
286			}
287			// The terminal comes back: wait for a SET after the child's snapshot.
288			waitOut(t, out, "the background after the child", func(s string) bool {
289				return len(s) > len(fe.snapshot()) && strings.Contains(s[len(fe.snapshot()):], bgSet)
290			})
291			p.Quit()
292		})
293		if err != nil {
294			t.Fatal(err)
295		}
296	
297		captured := fe.snapshot()
298		if captured == "" {
299			t.Fatal("the child never ran")
300		}
301		before := bgSequences(captured)
302		if len(before) < 2 || before[0] != setOf(defaultHex()) || before[len(before)-1] != bgReset {
303			t.Errorf("before the child: bgSequences = %q, want [SET ... RESET]", before)
304		}
305		after := bgSequences(got[len(captured):])
306		if len(after) < 2 || after[0] != setOf(defaultHex()) || after[len(after)-1] != bgReset {
307			t.Errorf("after the child: bgSequences = %q, want [SET ... RESET]", after)
308		}
309	}
